// Reset acquisition takes the same lock, so neither can cross the other's
// committed gate using a statement snapshot captured while waiting.
func (q *Queries) LockBotForSessionRunClaim(ctx context.Context, botID pgtype.UUID) (pgtype.UUID, error) {
	row := q.db.QueryRow(ctx, lockBotForSessionRunClaim, botID)
	var id pgtype.UUID
	err := row.Scan(&id)
	return id, err
}

const lockSessionRunForAgentStepCommit = `-- name: LockSessionRunForAgentStepCommit :one
SELECT run_id
FROM session_runs
WHERE team_id = public.memoh_current_team_id()
  AND run_id = $1
  AND bot_id = $2
  AND session_id = $3
  AND fencing_token = $4
  AND state IN ('running', 'waiting_decision')
  AND ($5::boolean OR abort_requested_at IS NULL)
FOR UPDATE
`

type LockSessionRunForAgentStepCommitParams struct {
	RunID        pgtype.UUID `json:"run_id"`
	BotID        pgtype.UUID `json:"bot_id"`
	SessionID    pgtype.UUID `json:"session_id"`
	FencingToken int64       `json:"fencing_token"`
	Interrupted  bool        `json:"interrupted"`
}

// Complete steps must precede abort intent; interrupted checkpoints only need
// the same active owner because some cancellation paths do not record intent.
func (q *Queries) LockSessionRunForAgentStepCommit(ctx context.Context, arg LockSessionRunForAgentStepCommitParams) (pgtype.UUID, error) {
	row := q.db.QueryRow(ctx, lockSessionRunForAgentStepCommit,
		arg.RunID,
		arg.BotID,
		arg.SessionID,
		arg.FencingToken,
		arg.Interrupted,
	)
	var run_id pgtype.UUID
	err := row.Scan(&run_id)
	return run_id, err
}

